const S: Record<string, CSSProperties> = {
  "root": {
    "display": "inline-flex",
    "alignItems": "center",
    "justifyContent": "center",
    "borderStyle": "solid",
    "cursor": "pointer",
    "fontFamily": "Montserrat, sans-serif",
    "fontSize": "16px",
    "fontWeight": 500,
    "lineHeight": "22px",
    "color": "#FFFFFF",
    "gap": "10px",
    "paddingBlock": "16px",
    "paddingInline": "32px",
    "borderWidth": "0px",
    "textTransform": "uppercase"
  },
  "iconLeft": {
    "display": "inline-flex",
    "flexShrink": 0
  },
  "iconOnlyIcon": {
    "display": "inline-flex",
    "flexShrink": 0
  },
  "label": {},
  "iconRight": {
    "display": "inline-flex",
    "flexShrink": 0
  }
};

/** Per-variant overrides, resolved per enum value: "prop-value:part" → styles. */
const V: Record<string, CSSProperties> = {
  "variant-default:root": {
    "backgroundColor": "#26282C"
  },
  "variant-orange:root": {
    "backgroundColor": "#F98A0B"
  },
  "variant-blanc:root": {
    "backgroundColor": "#FFFFFF",
    "color": "#26282C"
  },
  "variant-outlineBlanc:root": {
    "borderWidth": "2px",
    "borderColor": "#FFFFFF"
  },
  "variant-link:root": {
    "color": "#26282C",
    "borderRadius": "32px",
    "paddingBlock": "4px",
    "paddingInline": "0px"
  },
  "variant-outilneNoir:root": {
    "borderWidth": "2px",
    "borderColor": "#26282C",
    "color": "#26282C"
  },
  "variant-iconOnly:root": {
    "width": "52px",
    "height": "52px",
    "gap": "0px",
    "paddingInline": "16px",
    "borderWidth": "2px",
    "borderColor": "#26282C",
    "color": "#26282C"
  }
};

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Visual style of the button. */
  variant?: 'default' | 'orange' | 'blanc' | 'outlineBlanc' | 'link' | 'outilneNoir' | 'iconOnly';
  /** Shows the leading icon slot (which glyph: iconLeftGlyph, default arrow-left). Extracted from the BOOLEAN property « Icone gauche » added to the Figma masters on 2026-07-23. */
  iconLeft?: boolean;
  /** Shows the trailing icon slot (which glyph: iconRightGlyph, default arrow-right — the « → » of Link buttons). Extracted from the BOOLEAN property « Icone droite » added to the Figma masters on 2026-07-23. */
  iconRight?: boolean;
  /** Which governed icon (ds.icons registry) fills the leading icon slot, when shown (iconLeft). */
  iconLeftGlyph?: 'piqueray' | 'phone' | 'download' | 'pdf' | 'search' | 'user' | 'chevron-right' | 'chevron-left' | 'chevron-down' | 'chevron-up' | 'cart' | 'arrow-right' | 'arrow-left' | 'facebook' | 'instagram' | 'star' | 'external-link' | 'mail' | 'octicon-chevron-down12';
  /** Which governed icon (ds.icons registry) fills the trailing icon slot, when shown (iconRight). */
  iconRightGlyph?: 'piqueray' | 'phone' | 'download' | 'pdf' | 'search' | 'user' | 'chevron-right' | 'chevron-left' | 'chevron-down' | 'chevron-up' | 'cart' | 'arrow-right' | 'arrow-left' | 'facebook' | 'instagram' | 'star' | 'external-link' | 'mail' | 'octicon-chevron-down12';
}

/** Piqueray button. Seven variants extracted from the Figma « Bouton » set (Default, Orange, Blanc, Outline blanc, Link, Outline noir, Icône seule), bound to Piqueray primitives.

The label (children) is bound to the « Libelle » TEXT property, added to the master in the single Step 3 update (002-governed-icons-button) — the label is genuinely editable on both sides now, closing the 001 declared parity finding (it used to be static Figma text, not a component property).

The two nested icons are leading/trailing slots gated by the BOOLEAN properties « Icone gauche »/« Icone droite » (iconLeft/iconRight boolean props) and steerable to any icon in the governed registry (contracts/icons.registry.json, ds.icons) via the INSTANCE_SWAP-bound enum props iconLeftGlyph/iconRightGlyph (Figma properties « Glyphe gauche »/« Glyphe droite », preferredValues narrowed to the governed registry in the same Step 3 update; the code enum tracks the registry exactly — widened from 13 to 16 when spec 004 added the facebook/instagram/star social glyphs (icons.registry.json v1.1.0), while the Figma master's swap menu still lists the original 13, a named divergence legued to the next write-authorized iteration since spec 004 is read-only), defaulting to the file's own arrow-left/arrow-right glyphs.

Extracted by propose-figma's D5 lowering pass from the post-Step-0-cleanup dump, reviewed and adopted — not authored. Any icon a designer picks on a mockup page is reproducible in code by naming it; the enum is refused by name at build if it ever drifts from the registry. */
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  { variant = 'default', iconLeftGlyph = 'arrow-left', iconRightGlyph = 'arrow-right', iconLeft = false, iconRight = false, style, children, ...rest },
  ref,
) {
  return (
    <button ref={ref} style={{ ...S.root, ...(V[`variant-${variant}:root`] ?? {}), ...style }} data-icon-left={iconLeft || undefined} data-icon-right={iconRight || undefined} {...rest}>
      {iconLeft ? (<span style={{ ...S.iconLeft }} aria-hidden="true" dangerouslySetInnerHTML={{ __html: ICONS[iconLeftGlyph] }} />) : null}
{variant === 'iconOnly' ? (<span style={{ ...S.iconOnlyIcon }} aria-label={String(children)} dangerouslySetInnerHTML={{ __html: ICONS[iconLeftGlyph] }} />) : null}
<span style={{ ...S.label, ...(variant === 'iconOnly' ? {"display":"none"} : {}) }}>{children}</span>
{iconRight ? (<span style={{ ...S.iconRight }} aria-hidden="true" dangerouslySetInnerHTML={{ __html: ICONS[iconRightGlyph] }} />) : null}
    </button>
  );
});
